import{_ as n,o as s,c as a,b as e}from"./app-45e1adad.js";const p={},t=e(`<h1 id="mars3d-地图开发基础" tabindex="-1"><a class="header-anchor" href="#mars3d-地图开发基础" aria-hidden="true">#</a> Mars3D 地图开发基础</h1><h2 id="什么是-mars3d" tabindex="-1"><a class="header-anchor" href="#什么是-mars3d" aria-hidden="true">#</a> 什么是 Mars3D？</h2><p>Mars3D 是一款基于 WebGL 技术的开源三维地球和地图可视化开发平台。它基于 Cesium 优化而来，提供了更加易用的 API 和丰富的功能。</p><h2 id="核心特性" tabindex="-1"><a class="header-anchor" href="#核心特性" aria-hidden="true">#</a> 核心特性</h2><h3 id="🌍-三维地球展示" tabindex="-1"><a class="header-anchor" href="#🌍-三维地球展示" aria-hidden="true">#</a> 🌍 三维地球展示</h3><ul><li><strong>全球地形数据</strong>：支持多种高程数据源</li><li><strong>多图层管理</strong>：可同时加载多个数据图层</li><li><strong>坐标系统</strong>：支持 WGS84、Web 墨卡托等多种坐标系</li></ul><h3 id="🎯-数据可视化" tabindex="-1"><a class="header-anchor" href="#🎯-数据可视化" aria-hidden="true">#</a> 🎯 数据可视化</h3><ul><li><strong>矢量数据</strong>：点、线、面、模型等几何要素</li><li><strong>影像数据</strong>：支持多种图片格式和瓦片服务</li><li><strong>地形数据</strong>：真实地形模拟和自定义地形</li></ul><h3 id="⚡-高性能" tabindex="-1"><a class="header-anchor" href="#⚡-高性能" aria-hidden="true">#</a> ⚡ 高性能</h3><ul><li><strong>WebGL 加速</strong>：硬件加速渲染</li><li><strong>LOD 技术</strong>：多层次细节优化</li><li><strong>动态调度</strong>：智能数据加载和内存管理</li></ul><h2 id="基础概念" tabindex="-1"><a class="header-anchor" href="#基础概念" aria-hidden="true">#</a> 基础概念</h2><h3 id="_1-地图对象-map" tabindex="-1"><a class="header-anchor" href="#_1-地图对象-map" aria-hidden="true">#</a> 1. 地图对象 (Map)</h3><h2 id="wms图层服务" tabindex="-1"><a class="header-anchor" href="#wms图层服务" aria-hidden="true">#</a> WMS图层服务</h2><p>将该 WMS 图层添加到 Mars3D 地图中，核心是通过 Mars3D 提供的 <code>WmsLayer</code> 类配置 WMS 服务参数</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 假设在组件的 mounted 或地图初始化完成后执行</span>
<span class="token keyword">import</span> Mars3D <span class="token keyword">from</span> <span class="token string">&#39;mars3d&#39;</span>

<span class="token comment">// 地图初始化完成后的回调函数（关键：确保 map 实例已创建）</span>
<span class="token keyword">function</span> <span class="token function">addWmsLayerToMars3D</span><span class="token punctuation">(</span><span class="token parameter">map</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token comment">// 1. 配置 WMS 图层参数（解析你的 WMS 地址）</span>
  <span class="token keyword">const</span> wmsLayerOptions <span class="token operator">=</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">id</span><span class="token operator">:</span> <span class="token string">&#39;gis_zhongguo_jinfeiqu&#39;</span><span class="token punctuation">,</span> <span class="token comment">// 图层唯一标识（自定义）</span>
    <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;中国禁飞区&#39;</span><span class="token punctuation">,</span> <span class="token comment">// 图层名称（地图控件中显示）</span>
    <span class="token literal-property property">url</span><span class="token operator">:</span> <span class="token string">&#39;http://36.133.109.100:18060/geoserver/fph/wms&#39;</span><span class="token punctuation">,</span> <span class="token comment">// WMS 服务地址</span>
    <span class="token literal-property property">layers</span><span class="token operator">:</span> <span class="token string">&#39;fph:gis_zhongguo_jinfeiqu&#39;</span><span class="token punctuation">,</span> <span class="token comment">// 图层名（从 URL 中提取）</span>
    <span class="token literal-property property">srs</span><span class="token operator">:</span> <span class="token string">&#39;EPSG:4490&#39;</span><span class="token punctuation">,</span> <span class="token comment">// 坐标系（与 WMS 服务一致）</span>
    <span class="token literal-property property">version</span><span class="token operator">:</span> <span class="token string">&#39;1.1.0&#39;</span><span class="token punctuation">,</span> <span class="token comment">// WMS 版本（与 URL 一致）</span>
    <span class="token comment">// 关键参数：从原 URL 中提取</span>
    <span class="token literal-property property">parameters</span><span class="token operator">:</span> <span class="token punctuation">{</span>
      <span class="token literal-property property">service</span><span class="token operator">:</span> <span class="token string">&#39;WMS&#39;</span><span class="token punctuation">,</span>
      <span class="token literal-property property">request</span><span class="token operator">:</span> <span class="token string">&#39;GetMap&#39;</span><span class="token punctuation">,</span>
      <span class="token literal-property property">styles</span><span class="token operator">:</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">,</span> <span class="token comment">// 无自定义样式</span>
      <span class="token literal-property property">format</span><span class="token operator">:</span> <span class="token string">&#39;image/png&#39;</span><span class="token punctuation">,</span> <span class="token comment">// 图片格式（原 URL 是 application/openlayers，需改为 png 兼容）</span>
      <span class="token literal-property property">transparent</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token comment">// 透明背景（避免遮挡地图底图）</span>
      <span class="token literal-property property">bbox</span><span class="token operator">:</span> <span class="token string">&#39;75.813007,18.234234,134.582382,53.053349&#39;</span> <span class="token comment">// 初始显示范围（可省略，默认加载全量）</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token comment">// 图层显示配置</span>
    <span class="token literal-property property">visible</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token comment">// 初始是否显示</span>
    <span class="token literal-property property">opacity</span><span class="token operator">:</span> <span class="token number">0.7</span><span class="token punctuation">,</span> <span class="token comment">// 透明度（0-1，避免遮挡底图）</span>
    <span class="token literal-property property">clampToGround</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token comment">// 贴地显示（适配地形）</span>
    <span class="token literal-property property">zIndex</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token comment">// 图层层级（高于底图，低于业务图层）</span>
    <span class="token comment">// 可选：限制显示范围（避免超范围加载）</span>
    <span class="token literal-property property">extent</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token number">75.813007</span><span class="token punctuation">,</span> <span class="token number">18.234234</span><span class="token punctuation">,</span> <span class="token number">134.582382</span><span class="token punctuation">,</span> <span class="token number">53.053349</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token comment">// 可选：瓦片加载优化</span>
    <span class="token literal-property property">tileSize</span><span class="token operator">:</span> <span class="token number">256</span><span class="token punctuation">,</span> <span class="token comment">// 瓦片大小</span>
    <span class="token literal-property property">refreshInterval</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token comment">// 不自动刷新</span>
    <span class="token literal-property property">noDataValue</span><span class="token operator">:</span> <span class="token number">0</span> <span class="token comment">// 无数据值处理</span>
  <span class="token punctuation">}</span>

  <span class="token comment">// 2. 创建 WMS 图层实例</span>
  <span class="token keyword">const</span> wmsLayer <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Mars3D<span class="token punctuation">.</span>layer<span class="token punctuation">.</span>WmsLayer</span><span class="token punctuation">(</span>wmsLayerOptions<span class="token punctuation">)</span>

  <span class="token comment">// 3. 添加到地图并加载</span>
  map<span class="token punctuation">.</span><span class="token function">addLayer</span><span class="token punctuation">(</span>wmsLayer<span class="token punctuation">)</span>

  <span class="token comment">// 可选：监听图层加载状态</span>
  wmsLayer<span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span>Mars3D<span class="token punctuation">.</span>EventType<span class="token punctuation">.</span>load<span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;WMS 禁飞区图层加载成功&#39;</span><span class="token punctuation">)</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span>

  wmsLayer<span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span>Mars3D<span class="token punctuation">.</span>EventType<span class="token punctuation">.</span>error<span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">err</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    console<span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token string">&#39;WMS 图层加载失败：&#39;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span>

  <span class="token comment">// 可选：返回图层实例，方便后续控制（显示/隐藏/移除）</span>
  <span class="token keyword">return</span> wmsLayer
<span class="token punctuation">}</span>

<span class="token comment">// 调用示例（假设 map 是 Mars3D 地图实例）</span>
<span class="token comment">// 在地图初始化完成后调用</span>
<span class="token comment">// addWmsLayerToMars3D(map)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,15),o=[t];function l(c,r){return s(),a("div",null,o)}const u=n(p,[["render",l],["__file","mars3d.html.vue"]]);export{u as default};
